"use strict";

// Walkthroughs for the Using Kyro family part a (see howto-walkthroughs.js, walkthrough-kit.js and guide-walkthroughs.js). Kept in its own file so two writers can work on one family without touching the same lines.
// Every fact here is from the how-to sheets (the How-To Guide, the Voice Test, Open Everything, the Capability Reference and the Tester Guide, as read on 22 October 2026). Every phrase a step puts in quotation marks is one that those
// sheets or the live voice cases run (a test checks), and anything the sheets do not say is said plainly as "the guide does not say".

const { S, W } = require("./walkthrough-kit.js");

module.exports = {
  // the lesson for someone who has never used Kyro: the orb, speaking, typing, guest or signed in, what to say first
  "first-five-minutes": {
    title: "Your first five minutes with Kyro: the orb, talking, typing and signing in",
    topic: "howto-start", phrase: "using Kyro for the first time",
    steps: [
      S("Know what Kyro is", `Kyro is a voice assistant. You tap a round button called the orb and talk. Kyro answers out loud and shows what it found on the screen. It can keep your lists, notes, reminders and calendar, and tell you the weather. It works in six languages. Think of it as a helper you speak to, like a person who writes things down for you.`, ["Your phone or computer with Kyro open"], null, "you can say in your own words what Kyro does: you talk, it answers aloud and shows things on the screen.", [W("Kyro", "the voice assistant you are learning to use."), W("Orb", "the glowing round button with the letter K. You tap it to start talking."), W("Voice assistant", "a program you talk to, which answers you out loud.")]),
      S("Get ready to talk", `Use Google Chrome on a computer or on an Android phone. Safari on an iPhone has not been tested, so it may not work well. Sit somewhere quiet. A headset with a microphone works much better than the speaker, and it helps when Kyro repeats itself or answers its own words. Open Kyro by its own address, not through a link inside another app.`, ["Chrome on a computer or an Android phone", "A quiet place, and a headset with a microphone if you have one"], null, "Kyro is open in Chrome and you are somewhere quiet.", [W("Microphone", "the part of your phone or computer that hears you."), W("Headset", "earphones with a small microphone, worn on your head.")]),
      S("Tap the orb and allow the microphone", `Sign in, or press Start as User to look around as a guest. Then tap the glowing orb with the K. Your browser will ask to use the microphone. Press Allow. Wait until the screen says Nexus is listening. That can take up to about 25 seconds. If it says Microphone blocked, you pressed Block earlier. Click the lock or tune icon beside the address bar, set Microphone to Allow, reload the page, and tap the orb again.`, ["Kyro open, signed in or as a guest"], null, "the screen says Nexus is listening.", [W("Allow", "the button that lets Kyro use your microphone. Without it Kyro cannot hear you."), W("Browser", "the program, such as Chrome, that you use to open websites.")]),
      S("Say hello and ask what Kyro can do", `Say "Hello Kyro". Wait for the answer. Then say "What can you help me with?" You do not need a special word before you speak. Watch the words on the orb. Listening means the microphone is open. Hearing speech means Kyro hears you. Reviewing the request means it is thinking, which is normal for a few seconds. Speaking means Kyro is talking. Kyro may mishear its name as Kairo, Cairo or Kyra. That is fine.`, ["The microphone allowed and the orb listening"], null, "Kyro has answered you out loud and you have seen the orb words change.", [W("Reviewing the request", "what the orb says while Kyro is thinking about what you asked."), W("Wake word", "a special word some devices need before they listen. Kyro does not need one while the page is open.")]),
      S("Stop Kyro or change your mind", `You can talk over Kyro while it speaks, or say the word stop, pause or wait, and it should go quiet in about a second. Say "Hold on" to pause. If you want to give up on something for good, say "Never mind". To turn Kyro's voice off, say mute. To bring it back, say turn voice on. Talk to Kyro one request at a time, and wait for it to finish before you answer a question it asks.`, ["Kyro open and listening"], null, "you have talked over Kyro or told it to hold on, and it went quiet.", [W("Mute", "turn Kyro's voice off so it does not speak.")]),
      S("Know the difference between guest and signed in", `A guest can look around and chat. To start as a guest, type your name under No login yet and press Start as User. A guest cannot send messages, make calls, set up alerts, download data or delete data, and may lose what they save. If you have an account, sign in, and Kyro keeps your own lists, notes and records. There is no public sign-up: the owner makes accounts, so ask the person who gave you Kyro if you need one.`, ["The sign-in the owner gave you, if you have one", "A pen and paper to write the name of who to ask"], null, "you know whether you are a guest or signed in, and who to ask for an account.", [W("Guest", "someone using Kyro without an account. Their own records are not kept for them."), W("Signed in", "using Kyro with your own account, so your lists and notes are kept as yours.")]),
      S("Know what to do when Kyro goes quiet", `Wait ten seconds. Then say "Can you hear me?" If there is still no answer, check that your microphone is not muted and speak closer. If the orb stays on reviewing the request for more than 30 seconds, say stop and ask again, or reload the page. If voice is blocked or has failed, a typing box appears: type the same sentence you would say. Kyro sometimes goes quiet and the cause is not yet known. It tries to reconnect by itself. Keep the Kyro page open and in front.`, ["Kyro open, with the orb showing"], null, "you know three things to try when Kyro goes quiet: wait, ask if it can hear you, and type.", [W("Reload", "load the page again, so it starts fresh.")]),
      S("Choose one small habit and your next lesson", `Each day, say "Hello Kyro" and ask it one thing. Then pick a part of Kyro to learn next. You can ask Kyro to walk you through using the shopping list, the calendar, reminders or the notes screen, in your own words. Kyro will show one step at a time and read it out, and you do each step yourself.`, ["A pen and paper to write the one thing you will ask tomorrow"], null, "you have written down the one thing you will ask Kyro tomorrow and the part of Kyro you will learn next.", [])
    ]
  },

  "lists": {
    title: "Keeping a shopping list, a to-do list and checklists with Kyro",
    topic: "howto-lists", phrase: "using the shopping list and to-do list",
    steps: [
      S("Know the three kinds of list", `Kyro keeps one shopping list and one to-do list in your own words, and reads them back to you. It also makes named checklists, such as one called Seed Order. A named checklist is kept separately, so it does not show when you ask what is on your shopping list. Use a signed-in account. A guest may lose what they save.`, ["Kyro open and signed in"], null, "you can name the three kinds of list: shopping, to-do and named checklists.", [W("Checklist", "a list with a name that you tick off item by item."), W("Signed in", "using your own account, so Kyro keeps your lists as yours.")]),
      S("Make a shopping list", `Say "Make a shopping list with milk, eggs and bread". Use your own items. Speak slowly and name each item clearly. Kyro adds them to your shopping list and tells you how many items are still open. Listen to check it heard each item.`, ["Three things you really need to buy"], null, "Kyro has said it added your items to the shopping list.", []),
      S("Add something to your to-do list", `Say "I need to buy fertilizer, put it on my list". Use something you really need to do or buy. Kyro adds it to your to-do list and says how many open items you have. To start a to-do list with several things, say "Start a to-do list: fix the gate, buy seed". If Kyro adds your items to the wrong list, tell the person who gave you Kyro.`, ["One job you need to do this week"], null, "Kyro has said it added your job to the to-do list.", [W("To-do list", "a list of jobs you need to do.")]),
      S("Hear your lists read back", `Say "What's on my shopping list?" Kyro reads the items with numbers. Then say "Show me my to-do list" and Kyro shows your jobs on the screen. Check that each list holds only what you said. If an item is missing or wrong, take it off in the next step and say it again.`, ["Your lists, started in the last two steps"], null, "you have heard your shopping list read back and seen your to-do list on the screen.", []),
      S("Tick off or take off an item", `To tick off something you have bought, say "Mark milk as done", using your own item. Kyro says it ticked it off and how many are still open. To take an item off, say the word remove, then the item, then from my shopping list. Do the same for the to-do list. Check by asking for the list again.`, ["An item on your list to tick off"], null, "one item is ticked off or taken off, and the list read back no longer shows it as open.", []),
      S("Make a named checklist", `For a job with a name, say "Create a checklist called Seed Order with items seeds, sacks and scale". Use your own name and items. Then say "Show my checklists". The checklists fill the screen. Tap an item to tick it. Tap the small cross to take it off. Type in the Add box to add one. Say "Close it" to go back to the orb.`, ["A job that needs a short checklist"], null, "your checklist is on the screen with its items, and you have ticked one.", []),
      S("Know what lists cannot do", `Named checklists do not show when you ask about your shopping list. If you say only remember to buy seed, Kyro does not save it, because it could be a to-do or a reminder. Say it as a to-do, or ask for a reminder. If Kyro gives general advice instead of adding your items, say the list words again, or type the same sentence.`, ["Kyro open"], null, "you know a named checklist is separate and how to ask for a reminder instead.", [])
    ]
  },

  "notes": {
    title: "Writing down and finding notes with Kyro",
    topic: "howto-notes", phrase: "using the notes screen",
    steps: [
      S("Know what notes are for", `A note is a short sentence Kyro saves for you and reads back, newest first. Use it for small facts you do not want to forget, such as which cow is limping or what a pump needs. Use a signed-in account. A guest may lose what they save. Do not save secrets such as a PIN or password in a note.`, ["Kyro open and signed in"], null, "you can say what a note is for and one thing you will not put in a note.", [W("Note", "a short sentence that Kyro saves and reads back to you.")]),
      S("Write your first note", `Say "Write down that the cow is limping". Use a fact of your own. Kyro answers that it has noted your words. Another way is "Remember that the pump needs a new seal". Say the whole fact in one sentence. Kyro does not save a request that only says remember to do something, because that could be a job or a reminder.`, ["One small fact you want to keep"], null, "Kyro has said it noted your words.", []),
      S("Hear your notes read back", `Say "What are my notes?" Kyro reads your notes, newest first. Check that each one holds your own words. To see them on the screen, say "Show my notes". You will see a screen titled Your notes, with a box under it.`, ["Kyro open"], null, "you have heard or seen the note you wrote.", []),
      S("Type a note on the screen", `On the Your notes screen, type a note in the box under the list. Tap Save note. The screen says Saved and shows your note at the top. Typing is useful in a noisy place. Say "Close it" when you are finished and Kyro goes back to the orb.`, ["The Your notes screen open"], null, "your typed note is at the top of the list.", []),
      S("Delete a note", `To remove a note, say "Delete my note about the cow". Use a word from the note you want gone. Kyro removes only that note. Ask "What are my notes?" again to check that it is gone and the others are still there. If the wrong note went, write it again.`, ["A note you want to remove"], null, "the note is gone and the other notes are still there.", []),
      S("Know what notes cannot do", `Kyro will not save a PIN or a password in a note, and you should not try. Notes are words only. The guide does not say how to change a note once it is saved, so delete it and write it again. Notes belong to your account, so a guest may lose them.`, ["Kyro open"], null, "you know not to keep secrets in notes and how to fix a note by writing it again.", [])
    ]
  },

  "calendar": {
    title: "Putting an appointment on the calendar and asking what is coming",
    topic: "howto-calendar", phrase: "using the calendar",
    steps: [
      S("Know what the calendar does", `Kyro keeps events with a day and a time. It can add an event, tell you what is on a day, and remove an event. The events are kept inside Kyro. They are not copied to your phone's own calendar app, and Kyro cannot yet sync with a real calendar. Use a signed-in account.`, ["Kyro open and signed in"], null, "you know the calendar is inside Kyro and does not copy to your phone's calendar.", [W("Event", "something that happens on a day and time, such as a meeting or a vet visit."), W("Sync", "copy information between two apps so both match.")]),
      S("Add your first event", `Say "Add vet visit to my calendar tomorrow at 10 am". Use your own event. Say am or pm with the time. A bare hour such as at 3 is taken as 3 in the afternoon. Kyro adds the event, says the day and the time back to you, and says it will mention it in your morning brief that day. You do not need to say yes.`, ["An event with a day and an hour"], null, "Kyro has said your event, the day and the time back to you.", [W("Morning brief", "a message with the weather and what is due that day. You set it up in another lesson.")]),
      S("Add a second event another way", `Say "Put a meeting with the cooperative on Monday at 10 am". You can say put or add, and name the day. Listen to the day and time Kyro says back. If they are wrong, add the event again with the right day and time, and remove the wrong one in a later step.`, ["Another event, with a day and an hour"], null, "Kyro has repeated back the right day and time.", []),
      S("Ask what is on your calendar", `Say "What is on my calendar tomorrow?" Kyro lists what you have. Today, tomorrow, this week and next week work. A question about one named day, such as Monday, may not be understood. To see your dates on the screen, say "Open the calendar". Say "Close it" to go back.`, ["Kyro open and an event saved"], null, "Kyro has told you your event for tomorrow or this week.", []),
      S("Remove an event", `To take an event off, say cancel, then the name of the event, then from my calendar. For example, cancel vet visit from my calendar. Kyro says it removed it. Ask what is on your calendar again to check it is gone.`, ["The name of an event you want to remove"], null, "Kyro has said it removed the event and it no longer shows.", []),
      S("Know what the calendar cannot do", `The calendar does not copy to your phone's calendar app. A time with no am or pm may be saved with no time at all. The guide does not say that Kyro alerts you at the time of the event; it says it mentions the event in your morning brief. For a message at a set time, ask for a reminder, as in the reminders lesson.`, ["Kyro open"], null, "you know the calendar is not an alarm, and a reminder is.", [W("Reminder", "a message from Kyro at a time you choose.")])
    ]
  },

  "reminders": {
    title: "Setting, checking and stopping reminders with Kyro",
    topic: "howto-reminders", phrase: "setting a reminder",
    steps: [
      S("Know what a reminder is and what it needs", `A reminder is a message that Kyro sends to your phone at a time you choose. It can happen once or repeat. To get the message on your phone you need to turn on alerts and allow notifications. No one has yet proven that alerts reach phones in the real service. The guide does not say where the Enable alerts button is; ask the person who gave you Kyro.`, ["Kyro open and signed in", "Your phone, with notifications allowed"], null, "you know a reminder needs alerts turned on, and who to ask if you cannot find the button.", [W("Alerts", "messages Kyro sends to your phone even when the page is not in front."), W("Notification", "the small message that appears on your phone screen.")]),
      S("Try a reminder two minutes ahead", `To see how it works, say "Remind me to drink water in 2 minutes". Kyro repeats the task and the time back to you in plain words. Wait and see if the alert arrives on your phone. If it does not, write down the time you set and your phone's time zone, and tell the person who gave you Kyro.`, ["Your phone, with notifications allowed", "A pen and paper"], null, "Kyro has said the task and time back, and you have noticed whether the alert arrived.", [W("Time zone", "the clock setting for the part of the world where you are.")]),
      S("Set a real reminder", `Say "Remind me tomorrow morning to check the water tank". Use your own task. Say am or pm when you give a time. Tomorrow morning is 8 in the morning. A day with no time is 9 in the morning. Listen to the task and time Kyro says back, and check that they are right.`, ["One job you need to remember"], null, "Kyro has said your task and the time back to you.", []),
      S("Try other ways of saying it", `You can say it the way you really would. Say "Remind me in an hour to turn off the tap". Or say "Remind me on 15 October at 10 am about the clinic". Each time, Kyro repeats the task and the time. A time that has already gone today is moved to tomorrow, and Kyro says so. If anything sounds wrong, say the reminder again with a clearer time.`, ["Another job and a time"], null, "you have set another reminder and Kyro said it back.", []),
      S("See your reminders", `Say "What are my reminders?" or "Show my reminders". The screen lists your reminders. Under the list is a form with what, which day, what time, and a Set reminder button. You can also set one there. Say "Close it" to go back to the orb.`, ["Kyro open, with a reminder set"], null, "your reminders are on the screen and you can find the Set reminder button.", []),
      S("Cancel a reminder", `To cancel one, say cancel my reminder about, then the thing, for example cancel my reminder about the cow. Kyro may ask you to say yes. It names only the reminders that match. Ask for your reminders again to check it is gone.`, ["A reminder you want to cancel"], null, "the reminder is gone from the list.", []),
      S("Set a reminder that repeats", `Say "Remind me every morning at 8 to check the water pump". Say "Show my repeating reminders" to see them. To stop one, say "Stop my repeating reminder to check the water pump". Kyro refuses repeats it cannot do, such as yearly, every few months or every few days, and says it sets nothing. Stop any practice one so it does not keep sending alerts.`, ["A job you do every day"], null, "you have set, listed and stopped a repeating reminder.", [W("Repeating reminder", "a reminder that comes again on a schedule, such as every morning.")]),
      S("Know what reminders cannot do", `Kyro tells you what it set, but it cannot show you that the alert reached your phone. A reminder asked for in Kiswahili works, but no fluent speaker has yet checked the wording. Reminders belong to a signed-in account. If an alert never arrives, tell the person who gave you Kyro the time you set and your phone's time zone.`, ["A pen and paper"], null, "you know what to tell the owner if an alert never arrives.", [])
    ]
  },

  "contacts": {
    title: "Saving, finding and removing a phone number in Kyro",
    topic: "howto-contacts", phrase: "saving a phone number",
    steps: [
      S("Know what the contact list does", `Kyro can keep the names and phone numbers of people you know, and read them back. Calling and texting from Kyro are not part of this lesson. This lesson is only about keeping a number and finding it again. The contact list works in English only. Use a signed-in account.`, ["Kyro open and signed in"], null, "you know the contact list keeps names and numbers and reads them back.", [W("Contact", "a person whose name and phone number you keep.")]),
      S("Find the country code", `Kyro needs the country code at the front of the number. A country code starts with a plus sign. The example in this lesson starts with plus 254. The guide does not list country codes; if you do not know yours, ask someone you trust or your phone company. Write the full number on paper first, with the plus sign and the code, so you can read it out slowly and check it later.`, ["The full number of someone you know, with its country code", "A pen and paper"], null, "you have the full number written down with a plus sign and a country code.", [W("Country code", "the digits, after a plus sign, that show which country a phone number is in.")]),
      S("Save a number", `Say it in this shape: "Save Otieno's number as +254712345678". Use your own person's name and number. Say the digits slowly and clearly. Kyro should say it saved the name with the number. A long number said aloud can come out different in the written transcript, so listen to what Kyro reads back.`, ["The name and the number on your paper"], null, "Kyro has said the name and the number it saved.", [W("Transcript", "the written words of what Kyro heard you say.")]),
      S("Check the number is right", `Say "Who are my contacts?" Kyro lists your contacts with their numbers. Check each digit against your paper. If the number is wrong, remove the contact in the next step and save it again. If speaking the number does not work for you, try typing the same sentence.`, ["Your paper with the number"], null, "the number Kyro lists matches your paper digit for digit.", []),
      S("Remove a contact", `To remove one, say "Forget Otieno", using the name you saved. Kyro says it forgot the person. Ask "Who are my contacts?" again to check that the person is gone and the others are still there.`, ["The name of a contact you want to remove"], null, "the contact is gone from the list.", []),
      S("Know what the contact list cannot do", `The number must have its country code. A number said aloud may be saved wrong, so check each one by asking for your contacts. Contacts work in English only. Sending texts is switched off for now, and calling is not taught here. For practice, use a number you made up, not a real person's number.`, ["Kyro open"], null, "you know to check every saved number and that practice numbers should be made up.", [])
    ]
  },

  "memory": {
    title: "What Kyro remembers about you, and the memory book",
    topic: "howto-memory", phrase: "what Kyro remembers about you",
    steps: [
      S("Know what Kyro remembers", `Kyro remembers seven kinds of facts about you: your name, your town, your crops, your animals, your language, how big your farm is, and the work you do. You can tell Kyro, ask what it knows, and tell it to forget. Use a signed-in account. A separate memory book keeps short true memories for an older person, and the last steps explain it.`, ["Kyro open and signed in"], null, "you can name some of the seven kinds of facts Kyro remembers.", [W("Memory book", "a place where an older person's short true memories are written down and read back.")]),
      S("Tell Kyro a fact about you", `Say "My name is Amina Wanjiru", using your own name. Kyro says it will remember it. Then say "I live in Kisumu" with your own town. Say one fact at a time, on its own. If you say a fact and a request in one sentence, Kyro does the request and saves nothing. A month, such as March, is never saved as a town.`, ["Your name and the town you live in"], null, "Kyro has said it will remember your name and your town.", []),
      S("Ask what Kyro knows about you", `Say "What do you know about me?" Kyro lists what it has saved, such as your name and town, or says it has nothing saved. The list should be yours only. If Kyro says it will remember something but the list shows nothing, tell the person who gave you Kyro.`, ["Kyro open, with a fact saved"], null, "Kyro has listed the facts you told it.", []),
      S("Tell Kyro to forget", `To take back a fact, say forget my, then the kind of fact. For example, say "Forget my farm size". You can also say "Forget that I keep chickens". Saying "Forget that" on its own takes back the last one. Ask what Kyro knows about you again to check.`, ["A fact you told Kyro"], null, "Kyro has said it forgot the fact and the list no longer shows it.", []),
      S("Add a memory to the memory book", `The memory book is for short true memories, written by the person or by family they allow. Say "Add to my memory book. My sister Anna sang while she cooked every evening." Use a true memory of your own. One sentence is one memory. A memory with words that need a safety reply is not saved. The book is a comfort and a place to keep stories. It is not a treatment, and a dementia-care professional has not yet reviewed it.`, ["One true memory, in one sentence"], null, "you have added one memory and Kyro has confirmed it.", []),
      S("Hear a memory and hold one back", `Say "Tell me a memory" and Kyro reads one exactly as it was written, and says who wrote it. Say "Another memory" for the next. Say "What is in my memory book?" for the list. Kyro never adds to, shortens or corrects a memory. If a memory is sad, say "Hold back the memory about Joseph", with the right name, and it will not be read out on its own.`, ["Your memory book with at least one memory"], null, "you have heard a memory read back exactly as written.", []),
      S("Know what memory cannot do", `Kyro keeps only the seven kinds of facts and uses them mostly in the morning brief and the résumé. The memory book is English only, has no photos or recordings, and its family steps have not been tried with real accounts. It never quizzes you by asking whether you remember. If Kyro says it did not catch that, it has changed nothing.`, ["Kyro open"], null, "you know what the memory book does not do.", [])
    ]
  },

  "morning-brief": {
    title: "Setting up the morning brief, weather warnings and the weekly summary",
    topic: "howto-brief", phrase: "the morning brief, weather alerts and weekly summary",
    steps: [
      S("Know the three messages", `Kyro can send three kinds of message if you ask for them. The morning brief tells you the weather and what is due that day. A weather warning comes when serious weather is forecast. The weekly summary comes once a week. They only start when you ask for them. They need alerts turned on and a phone that is registered with Kyro.`, ["Kyro open and signed in", "Your phone, with notifications allowed"], null, "you can name the three messages and say that you must ask for each one.", [W("Morning brief", "a short message each morning with the weather and what is due."), W("Registered phone", "a phone that has told Kyro it may receive your alerts.")]),
      S("Check that alerts are on", `The messages arrive as alerts on your phone. You must press Enable alerts and allow notifications in the browser. The guide does not say where the Enable alerts button is; ask the person who gave you Kyro. Without alerts, nothing will arrive, even if Kyro says it has set the message.`, ["Your phone", "A pen and paper to write who you asked"], null, "alerts are on for this phone, or you know who to ask.", [W("Notifications", "the small messages an app shows on your phone.")]),
      S("Turn on the morning brief", `Say "Send me a morning brief at 7am". Use the hour you want. Listen to what Kyro says it has set, and write it down. The brief also mentions events you put on your calendar for that day.`, ["The hour you want your brief"], null, "Kyro has told you it set a morning brief and you have written down what it said.", []),
      S("Turn on weather warnings and the weekly summary", `Say "Warn me about storms". A warning comes only when serious weather is forecast, so you cannot make one happen to test it. Then say "Send me a weekly summary on Sunday at 6pm", with the day and hour you want. Write down what Kyro says each time.`, ["The day and hour you want your weekly summary"], null, "you have asked for both and written down what Kyro said.", []),
      S("Stop a message", `To stop the morning brief, say "Stop my morning brief". The guide does not give the exact words to stop the other two messages. Ask Kyro how to stop them, and write down what it says.`, ["A pen and paper"], null, "you have stopped the morning brief, or know how to ask for it.", []),
      S("Know what these messages cannot do", `Weather warnings come only for serious weather. Whether a message really reaches a phone has not been proven in the real service, so check the first morning that it arrives. If it does not, write down the time you set and your phone's time zone and tell the person who gave you Kyro. Weather warnings work in English only.`, ["A pen and paper"], null, "you know what to write down if a message does not arrive.", [])
    ]
  },

  "ask-and-media": {
    title: "Asking Kyro questions and for pictures, videos and music",
    topic: "howto-ask", phrase: "asking Kyro questions, and for pictures, videos and music",
    steps: [
      S("Know what you can ask for", `Kyro can look things up on the web, find pictures and videos, play music, and tell you the weather. When it looks something up it shows the pages it used. An answer with no pages shown is only a guess, so treat it that way. If Kyro finds no checked source, it says so. These need the internet.`, ["Kyro open and connected to the internet"], null, "you know an answer with pages shown is better than one without.", [W("Source", "the web page an answer came from.")]),
      S("Ask for the weather", `Say "What is the weather in Kisumu today?" Use your own town. Kyro answers in degrees Celsius for the town you named, and on the orb a weather card appears with the same information. Say "Close the weather card" when you have seen it, and Kyro goes back to the orb.`, ["The name of your town"], null, "Kyro has told you the weather for your town and you have closed the card.", [W("Celsius", "the scale for measuring temperature used in most of the world.")]),
      S("Ask a question that needs the web", `Say "What is the price of maize in Kisumu today?" Use your own crop and town. Kyro may ask for a town or region first; answer it. It can take 15 to 20 seconds. The answer shows the pages Kyro used. Prices differ by market and date, so Kyro may say the sources disagree. That is correct. A price is never given from memory: with no source, Kyro says it could not find a checked price.`, ["A crop and a town"], null, "Kyro has answered and shown its pages, or said plainly it found no checked source.", []),
      S("Ask for pictures", `Say "Show me pictures of maize", with a thing you want to see. Or say "Open images" and Kyro asks what you want to see; answer it. Pictures can take a few seconds. Picture search needs a separate service that may not be switched on yet. If Kyro says it cannot find pictures, that may be the reason.`, ["Something you want to see pictures of"], null, "pictures are on the screen, or Kyro has said plainly it could not find any.", []),
      S("Ask for videos", `Say "Show me videos about composting", with something you want to learn. Videos come up on the screen. Tap one to play it. Say "Play a video about drip irrigation" to start one directly. Your phone may need one tap on play before the sound starts.`, ["Something you want to learn about"], null, "a video is on the screen and playing.", []),
      S("Play and stop music", `Say "Play some music". A player bar appears and music starts. Say "Pause the music" to pause it and "Resume the music" to carry on. Say "Stop the music" to close the player. Music plays from a video service only, and your phone may need one tap on play first.`, ["Your volume turned to a comfortable level"], null, "music has played, paused and stopped when you asked.", []),
      S("Know what these cannot do", `Kyro shows what it found, and sources can disagree, so read the pages it shows. Prices and crop advice are only as good as those pages. Price alerts do not exist. For an emergency, do not ask Kyro: call your local emergency number.`, ["Kyro open"], null, "you know to read the pages Kyro shows and that price alerts do not exist.", [])
    ]
  },

  "screens": {
    title: "Opening a screen by voice and closing it again",
    topic: "howto-screens", phrase: "opening and closing screens",
    steps: [
      S("Know how screens work", `Kyro shows one task on the screen at a time. When you ask for a list or a card, it fills the screen. It stays until you close it. After a quiet while, the screen goes back to the orb by itself. Starting a new request replaces the old screen, so nothing is left behind it.`, ["Kyro open, showing the orb"], null, "you know a screen stays until you close it, and that a new request replaces it.", [W("Card", "a panel that opens on the screen for one task, such as the weather."), W("Screen", "what you see on your phone or computer.")]),
      S("Open the documents screen", `Say "Open documents". A full screen titled Saved documents appears, with a box to save a new one. If it does not open, say "Can you pull up my documents?" The same screen should appear. Take a moment to look at what is on it.`, ["Kyro open and signed in"], null, "the Saved documents screen is open in front of you.", []),
      S("Close it and return to the orb", `Say "Close it", or say "Close the screen". The screen goes away and you are back at the orb. You can also press the Escape key on a computer, click the dark area outside the box, or press the Close button. During a guided task, say "Never mind" to stop it.`, ["A screen open"], null, "the screen has closed and you can see the orb again.", []),
      S("Open a list screen and then another", `Say "Show my notes". A screen titled Your notes opens. Without closing it, say "Show my checklists". The notes screen is replaced by your checklists. Then say "Show my reminders" to see a third. Each one replaces the last, and none is left behind.`, ["Kyro open"], null, "each new screen replaced the one before it.", []),
      S("Open the weather card and close it", `Say "Show me the weather". If Kyro asks which town, say it. A weather card appears. Then say "Close the weather card". You can also say "Back to the orb" or "Go back" to return. Try each one on a different screen until you know which words feel natural.`, ["The name of your town"], null, "you have opened a card and closed it with your voice.", []),
      S("Know what to do if a screen will not close", `Press the Escape key, click the dark area outside the box, or press the Close button. During a guided task, say "Never mind". If none of these works, the guide does not say more. Take a picture of the screen with your phone and show it to the person who gave you Kyro.`, ["Your phone, to take a picture if needed"], null, "you know four ways to close a screen that will not go away.", [])
    ]
  },

  "language": {
    title: "Changing the language Kyro speaks and understands",
    topic: "howto-language", phrase: "changing the language",
    steps: [
      S("Know which languages Kyro offers", `Kyro speaks and understands six languages: English, French, Kiswahili, Arabic, Spanish and Portuguese. Kiswahili was the first second language built. Some parts of Kyro are English only. The last step lists them, so you know before you rely on one.`, ["Kyro open"], null, "you can name the six languages.", [W("Kiswahili", "the Swahili language, spoken across East Africa.")]),
      S("Pick a language on the screen", `On the sign-in screen, find the language box and pick your language. You can also pick it from the menu at the top. The menus change to the language you chose. Then start Kyro as usual by tapping the orb.`, ["Kyro open at the sign-in screen"], null, "the menus and words on the screen are in the language you picked.", [W("Menu", "a list of choices you tap, often at the top of the screen.")]),
      S("Say hello in your language", `Tap the orb and say a greeting in the language you picked. For Kiswahili, say "Habari Kyro". Then ask for one everyday thing in the same language. Kyro should answer in your language and stay in it. Write down any word that sounds odd, exactly as Kyro said it.`, ["A pen and paper to write odd words"], null, "Kyro has answered you in your language.", []),
      S("Switch by voice", `Say "Speak Swahili" to switch to Swahili. Say "Speak English" to switch back. Listen to see if Kyro follows. You can use the same words to switch whenever you like.`, ["Kyro open and listening"], null, "Kyro has switched to the other language and back.", []),
      S("Fix the wrong language", `If Kyro answers in the wrong language, say "Speak English", then check the language box at the top of the screen. If Kyro keeps using the wrong language, write down the language you set, the language you spoke, and what Kyro said, and tell the person who gave you Kyro.`, ["A pen and paper"], null, "Kyro is answering in the language you want, or you have written down what went wrong.", []),
      S("Know what works in which language", `The Kiswahili wording is a first draft that no fluent speaker has approved yet. Reminders and calendar events work in Kiswahili. For example, "Nikumbushe kesho saa tatu asubuhi kunywesha ng'ombe" sets a reminder for 9 in the morning tomorrow, because saa tatu asubuhi means 9 in the morning. Calls, texts, contacts, check-ins, medicine reminders, weather alerts, offline notes, the guides and the voice interviews are English only for now.`, ["Kyro open"], null, "you know reminders work in Kiswahili and the other parts are English only.", [])
    ]
  },

  "signing-in": {
    title: "Signing in, staying signed in and using Kyro as a guest",
    topic: "howto-signin", phrase: "signing in and staying signed in",
    steps: [
      S("Know the two ways in", `You can use Kyro as a guest or with your own account. A guest can look around and chat. A signed-in person keeps their own records. There is no public sign-up: the owner makes the accounts. If you do not have one, ask the person who gave you Kyro.`, ["Kyro open at the sign-in screen"], null, "you know the difference between a guest and a signed-in person, and who makes accounts.", [W("Guest", "someone using Kyro without an account."), W("Account", "your own place in Kyro, with a sign-in that is only yours.")]),
      S("Start as a guest to look around", `On the sign-in screen, type your name under No login yet. Press Start as User. Then tap the orb and say "Hello Kyro". A guest cannot send messages, make calls, set up alerts, download data or delete data. Kyro tells you plainly when something needs an account. Guests may lose what they save, and a guest session ends by itself after about 12 hours.`, ["Kyro open at the sign-in screen"], null, "you are in as a guest and Kyro has said hello back.", []),
      S("Sign in with your own account", `Type your own email and sign-in details into the boxes yourself. Do not use the pre-filled demo box or the demo level buttons, because everyone shares those. Clear the box and type your own. Never say your sign-in details aloud to Kyro or write them in a note. Kyro does not need them.`, ["The sign-in details the owner gave you, kept private"], null, "you are signed in and Kyro is showing the orb.", [W("Sign in", "tell Kyro who you are, using your own email and secret details, so it opens your records.")]),
      S("Know how long a sign-in lasts", `A sign-in stays open while you are using Kyro. It ends 24 hours after you first signed in, and that limit is fixed. Guest sessions are separate. So if you sign in in the morning, expect to sign in again the next day.`, ["Kyro open"], null, "you know a sign-in ends 24 hours after you first signed in.", []),
      S("Sign in again when it has ended", `When a sign-in has ended, Kyro says so plainly instead of going quiet. Tap Sign in again and sign back in with your own details. If it ends sooner than you expected, write down the time and how long you had been signed in, and tell the owner.`, ["Your sign-in details, kept private", "A pen and paper"], null, "you are signed back in, or you know to tap Sign in again.", []),
      S("Log out when you finish", `To leave, use the Log out choice in the Settings menu. This matters on a shared phone or computer. The orb screen hides the Settings menu on purpose, and the guide does not say how to reach it from there. Ask the person who gave you Kyro. A guest session ends by itself after about 12 hours.`, ["Kyro open"], null, "you know how to log out, or you know who to ask.", [W("Log out", "end your sign-in so the next person cannot use your account.")])
    ]
  },

  "installing": {
    title: "Installing Kyro on your phone as an app",
    topic: "howto-install", phrase: "installing Kyro as an app",
    steps: [
      S("Know what installing does", `Kyro can be added to the home screen of your phone, and then it opens like an app, full screen. It is the same Kyro, just easier to open. The guide tested Android phones with Chrome first.`, ["Your phone, with Kyro open in Chrome"], null, "you know installing puts a Kyro icon on your home screen.", [W("Home screen", "the first screen on your phone, where app icons sit.")]),
      S("Install on an Android phone", `Open the Kyro address in Chrome. Tap the three dots menu. Then tap Install app or Add to Home screen. Follow what the phone shows. An icon named Kyro appears on your home screen.`, ["An Android phone with Chrome", "The Kyro address, open in Chrome"], null, "an icon named Kyro is on your home screen.", [W("Chrome", "the web browser program from Google.")]),
      S("If you have an iPhone", `On an iPhone with Safari, the choice is called Share, then Add to Home Screen. This has not been tested, so the guide cannot promise it works. Try it, and if something odd happens, write down exactly what you saw and tell the person who gave you Kyro.`, ["An iPhone, with Kyro open in Safari", "A pen and paper"], null, "you have tried it and written down what happened.", [W("Safari", "the web browser program on an iPhone.")]),
      S("Open Kyro from the icon", `Tap the new Kyro icon. It should open full screen and show the orb. Sign in and tap the orb as you did before. Check that you can talk to it.`, ["The Kyro icon on your home screen"], null, "Kyro opened from the icon and shows the orb.", []),
      S("Fix a blank or old screen", `If the app opens to a blank screen, or looks like an old version that will not update, close the app and open it again. Pull down on the screen to reload. On a computer, hold Ctrl and Shift and press R. If it stays wrong, tell the person who gave you Kyro what you see.`, ["Kyro open"], null, "Kyro shows the orb or the sign-in screen, not a blank page.", [W("Reload", "load the page again so it starts fresh.")]),
      S("Know what to expect and how to remove it", `With the internet off, only the screen frame opens and voice does not work. Kyro has not been checked on a real low-end phone yet. To remove the app, press and hold the icon and choose Uninstall or Remove.`, ["Your phone"], null, "you know what happens with no internet and how to remove the icon.", [])
    ]
  },

  "offline-notes": {
    title: "Keeping notes when there is no signal, with the offline notes screen",
    topic: "howto-offline", phrase: "using the offline notes screen",
    steps: [
      S("Know what offline notes are", `Sometimes you have no signal. Kyro keeps a short plain record note on your phone, such as a sale, a spend, rain or a harvest, and sends it later when you are back online. Voice does not work offline, so you type the note. Notes are kept for about three days. Use a signed-in account.`, ["Kyro open and signed in"], null, "you know offline notes are typed, kept on the phone, and sent later.", [W("Offline", "with no internet connection."), W("Record note", "a short line about a sale, a spend, rain or a harvest.")]),
      S("Open Kyro while you still have signal", `Before you go offline, open Kyro and sign in while you have signal. The page must already be open before you go offline. Say "Open the offline notes screen" to see the screen while you are online. It tells you that you are online and no notes are waiting on this phone, and it has a Send them now button.`, ["Kyro open and signed in, with signal"], null, "the offline notes screen says you are online and no notes are waiting.", []),
      S("Type a short note with no signal", `Turn on aeroplane mode to practise. Voice will not work, so type a short plain note, such as a sale of five bags of maize. Use a made-up note when practising. A typed box should appear. Kyro should say it saved the note on the phone. If it offers nothing to type into, write down what you saw.`, ["Your phone, with aeroplane mode ready to switch on"], null, "Kyro has said it saved the note on the phone.", [W("Aeroplane mode", "a phone setting that turns off all connections.")]),
      S("Reconnect and check", `Turn aeroplane mode off and wait about ten seconds. Kyro should say it sent the notes and tell you to check your records. It does not claim they were added. Then say "Open the offline queue" to see if any notes are still waiting. Check your records to see the note once, not twice.`, ["Your phone, now with signal"], null, "Kyro said it sent the note and your records show it once.", []),
      S("Know which notes are kept and which are not", `A note about a call, a text, a payment or a delete is never kept for later. A note that is too long is not kept; the guide gives different sizes in different places, so keep notes short. A note older than about three days is dropped, because the farm book records a note on the day it arrives and a late one would be wrong. If a note disappears, tell the person who gave you Kyro.`, ["A pen and paper"], null, "you know which notes are kept for later and which are not.", []),
      S("Know what offline cannot do", `Voice does not work offline. Only typed record notes are kept. Offline mode is small and has not been checked on a real low-end phone. When you are back online, check your records to be sure each note arrived. If something is important, write it on paper as well.`, ["Paper and a pen"], null, "you know voice does not work offline and you will check your records afterwards.", [])
    ]
  },

  "privacy-data": {
    title: "Using the privacy and data screen to download or delete your data",
    topic: "howto-privacy", phrase: "using the privacy and data screen",
    steps: [
      S("Know what the screen is for", `The Privacy and data screen lets you download a copy of your data, or delete your account and data, with clear words about what each does. It needs a real account. A guest cannot use it, and a guest is told there is no account data to download.`, ["Kyro open and signed in with your own account"], null, "you know the screen has a download choice and a delete choice, and needs a real account.", [W("Account data", "the records Kyro saved under your account, such as your notes and lists.")]),
      S("Open the screen and read it", `Open the Settings menu at the top and choose Privacy and data. You can also use the Privacy and data button at the top right. You will see four choices: Download a copy of my data, Delete my account and data, No keep my account, and Close. The guide says the orb screen hides the Settings menu, and does not say how to reach it from there. Ask the person who gave you Kyro.`, ["Kyro open and signed in"], null, "the screen is open and you can read all four choices.", [W("Settings menu", "the list of choices at the top of the screen for things like logging out.")]),
      S("Practise closing it", `Press Close. Then open it again and press the Escape key on a computer, or tap outside the box. It should close each way. Do this before you press anything else, so you know you can leave. Do not press Delete my account and data to practise.`, ["The Privacy and data screen open"], null, "you have closed the screen in at least two ways.", []),
      S("Download a copy of your data", `Press Download a copy of my data. A file downloads or opens in a new tab, and a message says how many records and files it holds. Open it and check it holds only your own records. Keep the file private, because it is about you. Delete the file from your computer when you have finished with it. If you ever see another person's records in it, stop and tell the owner at once.`, ["Your computer or phone", "A private place to keep the file"], null, "you have the file and it holds only your own records.", []),
      S("Understand the delete choice", `The delete choice opens a red box that asks you to type the word DELETE. Read it carefully. The choice No keep my account backs out. Deleting removes what Kyro saved under your account. Think about it first, and do not press it on an account you want to keep.`, ["The Privacy and data screen open"], null, "you can say what the delete choice does and how to back out of it.", []),
      S("Know what the download leaves out", `The download covers everything saved under your account, including shared lists saved since owner marks were added. Records saved before that have no owner, so the download lists them as not included. Payment and wallet records are kept for accounting on purpose, and the screen says so. Deleting newer records runs as a background job, so it is not instant.`, ["Kyro open"], null, "you know the download lists what it leaves out, and that payment records are kept on purpose.", [])
    ]
  },

  "uploading-files": {
    title: "Uploading a picture, PDF, Word or Excel file for Kyro to read out",
    topic: "howto-upload", phrase: "uploading a file",
    steps: [
      S("Know what you can upload", `You can upload a picture, a PDF, a Word file (.docx or the older .doc) or an Excel file (.xlsx or the older .xls), up to 10 megabytes. Kyro reads it out and shows it on the screen. A long file is read a part at a time. Each person has 50 megabytes of space. Use a signed-in account.`, ["Kyro open and signed in"], null, "you can name the kinds of file you can upload.", [W("Upload", "send a file from your phone or computer to Kyro."), W("Megabyte", "a measure of how big a file is.")]),
      S("Pick a practice file", `Use a file with made-up words or numbers for practice, never real people's records. A Word file with a few paragraphs, or an Excel file with a few rows, a date and a total, is ideal. Kyro does not read macro files or files locked with a password, and it does not read Word or Excel files from before 1997.`, ["A small file with made-up content, saved on your phone or computer"], null, "you have a small practice file ready to choose.", [W("Macro file", "a Word or Excel file that carries small programs inside it.")]),
      S("Open the uploads screen", `Say "Open uploads". A screen appears that says to choose a picture, a PDF, a Word document or an Excel file, with a green Choose a file button. You can also say "I want to upload a Word document" or "Upload my Excel spreadsheet". Each opens the same screen.`, ["Kyro open and signed in"], null, "the uploads screen is open with a Choose a file button.", []),
      S("Choose the file and wait", `Tap Choose a file and pick your practice file. Kyro says it is looking, and this can take up to 20 seconds. Then it reads out what is in the file and shows it on the screen. Word is read as paragraphs, with a table row read as a line. Excel is read as rows, with dates shown as dates and the results of formulas, and hidden sheets are left out and said so.`, ["Your practice file"], null, "Kyro has read out what is in the file.", []),
      S("Move through a long file", `If the file is long, Kyro tells you which part of how many it is reading. Say "Read the next part" to go on. Say "Part 3" to jump to that part. Say "Read the last part" to hear the end. After the last part Kyro says it has read all of the file.`, ["A long practice file, if you have one"], null, "you have moved from one part to another, or you know the words to use.", []),
      S("Read it straight away", `Read a file right after you upload it. A file can be gone after the site restarts. If Kyro says it cannot find the file, upload it again and note the time. This is a known problem, and the owner is checking the storage. Do not keep your only copy of anything in Kyro.`, ["Your practice file, still on your phone or computer"], null, "you read the file straight after uploading it, and you still have your own copy.", []),
      S("Know what Kyro cannot read", `Kyro does not read macro files, password-protected files, Word templates, rich text files, or pictures, charts and comments inside a Word or Excel file. A very big sheet is read only up to its first 5,000 rows. There is no screen yet to list or delete single files. If Kyro says it cannot read a file, open it and save it again as a plain Word or Excel file.`, ["Kyro open"], null, "you know which files Kyro cannot read and what to try when it says so.", [])
    ]
  },

  "documents": {
    title: "Making, opening and changing a document with Kyro",
    topic: "howto-documents", phrase: "making a document in Kyro",
    steps: [
      S("Know what documents are", `Kyro can make a document for you from words you say, read it back, and keep a list of your documents. You can download a document as a file. Documents are drafts of your own words, so check them before you use them. Use a signed-in account.`, ["Kyro open and signed in"], null, "you know a document is a draft made from your own words that you can download.", [W("Document", "a file with words in it, such as a plan or a note, that you can read and download."), W("Draft", "a first version that you check and change.")]),
      S("Open your saved documents", `Say "Open documents". A full screen titled Saved documents opens, with your documents newest first and a box to save a new one. If it does not open, say "Can you pull up my documents?" Say "Close it" when you want to go back to the orb.`, ["Kyro open and signed in"], null, "the Saved documents screen is open.", []),
      S("Make a document by voice", `Say "Make a document called Harvest Notes that says planted maize today". Use your own title and words. A document screen opens with the title, your words in a box, and Save changes and Download buttons. The words after called or named are the title. If you end with and save it, those words are not put in the document.`, ["A title and one sentence for a document"], null, "a document screen is open with your title and your words in it.", []),
      S("Change the words and save", `Click in the box and change a word. Then tap Save changes. The screen says Saved. Open the document again from the Saved documents screen to check your change is there. The document holds only the words you asked for, so add anything else yourself.`, ["The document open on the screen"], null, "you opened the document again and your change was there.", []),
      S("Download your own copy", `Tap Download yourself. The file goes to your phone or computer. Kyro does not send it to anyone. Keeping your own copy matters because documents made before a recent change may be lost when the app is updated.`, ["Your phone or computer"], null, "the file is saved on your phone or computer.", []),
      S("Ask for a report", `If you say "Make me a report about maize prices and save it", Kyro asks what the report should say, instead of saving your request as the document. Answer with the words you want in it. Plans, flyers and agreements are only starting points built from templates, and nothing is sent, published or signed.`, ["Words you want in a report"], null, "Kyro has asked what the report should say, and you have answered.", []),
      S("Know what documents cannot do", `A copy of each saved file, up to 3 megabytes, is kept so new documents survive app updates. Older documents may still be lost at an update. Kyro does not send or sign a document for you. For anything important, download your copy.`, ["Kyro open"], null, "you know to download your own copy of anything important.", [])
    ]
  },

  "automations": {
    title: "Connecting an outside tool and sending it one message with automations",
    topic: "howto-automations", phrase: "connecting an outside tool with automations",
    steps: [
      S("Know what an automation is", `An automation connects Kyro to an outside tool that does a job for you after it gets a message. You connect the link the outside tool gave you. Then you can send it one message by voice. Kyro reads the message back first, and the message goes only if you say yes. This needs a full signed-in account. It has not yet been tried with a real outside account, so practise first.`, ["Kyro open and signed in with a full account"], null, "you know an automation sends one message to an outside tool, only after you say yes.", [W("Outside tool", "another program or website that can do a job after getting a message from Kyro."), W("Automation", "a link you connect so that Kyro can send one message to an outside tool.")]),
      S("Get a practice link", `The outside tool gives you a link, which is a normal web address starting with https. For practice, ask the owner for a throwaway test link and never use a real business's link. Keep the link private. You will type or paste it, never say it aloud. After you connect it, it is never shown again. You can connect up to 10, and send up to 30 messages a day.`, ["A throwaway test link from the owner, kept private", "A pen and paper for the name you will give it"], null, "you have a practice link and a short name for it written down.", [W("Link", "a web address that the outside tool gives you to receive messages.")]),
      S("Open the automations screen", `Say "Open automations". A screen titled Outside tool automations appears, with a box for a name, a box for a link, and a Connect it button. A guest is told that connecting needs a full account.`, ["Kyro open and signed in"], null, "the automations screen is open with a name box, a link box and a Connect it button.", []),
      S("Connect your practice link", `Type a short name, such as sales sheet, in the name box. Paste the link in the link box. Tap Connect it. Do not say the link aloud. The link is not shown to you again, so keep your own copy somewhere private.`, ["Your practice link and name"], null, "the automation is connected and the screen shows its name.", []),
      S("Ask Kyro to list your automations", `Say "Show my automations". Kyro lists the ones you connected. With none connected, it tells you that you have none and to say open automations. Check that the name you gave is in the list.`, ["Kyro open"], null, "your automation's name is in the list.", []),
      S("Send one message, saying no first", `Use the name you gave. If you named it sales sheet, say "Send hello to my sales sheet automation". Kyro reads back the name and the exact words and waits. Say no first, and check that nothing is sent. Say the sentence again and say yes only when you mean it. Yes sends exactly one message, and Kyro says the outside service accepted it. A name Kyro does not know gets a plain reply that nothing was sent.`, ["Your practice automation, connected"], null, "you said no and nothing was sent, then you said yes and exactly one message went.", []),
      S("Remove it when you finish", `When you are done practising, open the automations screen and tap Remove twice. A message that has already been sent cannot be taken back, so be careful what you send. Kyro sends a message to an outside tool only after your clear yes.`, ["The automations screen open"], null, "your practice automation is gone from the list.", [])
    ]
  }
};
